// Binary Search Tree — insert, search, and all four traversals
class BSTNode {
  constructor(val) {
    this.val = val;
    this.left = null;
    this.right = null;
  }
}

class BST {
  #root = null;

  // O(log n) balanced, O(n) worst-case (degenerate tree)
  insert(val) {
    const node = new BSTNode(val);
    if (!this.#root) { this.#root = node; return this; }
    let cur = this.#root;
    while (true) {
      if (val < cur.val) {
        if (!cur.left)  { cur.left  = node; return this; }
        cur = cur.left;
      } else {
        if (!cur.right) { cur.right = node; return this; }
        cur = cur.right;
      }
    }
  }

  // O(log n) balanced — halves search space at each step
  search(val) {
    let cur = this.#root;
    while (cur) {
      if (val === cur.val) return true;
      cur = val < cur.val ? cur.left : cur.right;
    }
    return false;
  }

  // In-order: produces sorted ascending output from a BST
  inOrder(node = this.#root, out = []) {
    if (!node) return out;
    this.inOrder(node.left, out);
    out.push(node.val);
    this.inOrder(node.right, out);
    return out;
  }

  // Pre-order: visit root before subtrees — good for serialisation
  preOrder(node = this.#root, out = []) {
    if (!node) return out;
    out.push(node.val);
    this.preOrder(node.left, out);
    this.preOrder(node.right, out);
    return out;
  }

  // Post-order: children before parent — good for deletion / eval
  postOrder(node = this.#root, out = []) {
    if (!node) return out;
    this.postOrder(node.left, out);
    this.postOrder(node.right, out);
    out.push(node.val);
    return out;
  }

  // Level-order (BFS) — uses a queue, O(n) time, O(w) space (w = max width)
  levelOrder() {
    if (!this.#root) return [];
    const out = [];
    const queue = [this.#root];
    while (queue.length) {
      const node = queue.shift();
      out.push(node.val);
      if (node.left)  queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    return out;
  }
}

const bst = new BST();
[8, 3, 10, 1, 6, 14, 4, 7].forEach(v => bst.insert(v));

console.log(bst.search(6));       // true
console.log(bst.search(99));      // false
console.log(bst.inOrder());       // [1, 3, 4, 6, 7, 8, 10, 14]  ← sorted
console.log(bst.preOrder());      // [8, 3, 1, 6, 4, 7, 10, 14]  ← root first
console.log(bst.postOrder());     // [1, 4, 7, 6, 3, 14, 10, 8]  ← leaves first
console.log(bst.levelOrder());    // [8, 3, 10, 1, 6, 14, 4, 7]  ← BFS

// Min-Heap — array-backed, O(log n) push/pop, O(1) peek
class MinHeap {
  #h = [];

  // Index arithmetic — the entire structure in three lines
  #parent = i => Math.floor((i - 1) / 2);
  #left   = i => 2 * i + 1;
  #right  = i => 2 * i + 2;

  // O(log n) — append then bubble up
  push(val) {
    this.#h.push(val);
    let i = this.#h.length - 1;
    while (i > 0) {
      const p = this.#parent(i);
      if (this.#h[p] <= this.#h[i]) break; // heap property satisfied
      [this.#h[p], this.#h[i]] = [this.#h[i], this.#h[p]];
      i = p;
    }
  }

  // O(log n) — swap root with last, shrink array, sift down
  pop() {
    if (this.#h.length === 0) return undefined;
    if (this.#h.length === 1) return this.#h.pop();
    const min = this.#h[0];
    this.#h[0] = this.#h.pop(); // move last element to root
    let i = 0;
    while (true) {
      let smallest = i;
      const l = this.#left(i);
      const r = this.#right(i);
      if (l < this.#h.length && this.#h[l] < this.#h[smallest]) smallest = l;
      if (r < this.#h.length && this.#h[r] < this.#h[smallest]) smallest = r;
      if (smallest === i) break; // already in correct position
      [this.#h[i], this.#h[smallest]] = [this.#h[smallest], this.#h[i]];
      i = smallest;
    }
    return min;
  }

  peek()       { return this.#h[0]; }         // O(1) — just read index 0
  get size()   { return this.#h.length; }
  get isEmpty(){ return this.#h.length === 0; }
}

// Usage demonstration
const heap = new MinHeap();
[5, 3, 8, 1, 9, 2, 7].forEach(v => heap.push(v));
// Internal array after all inserts: [1, 3, 2, 5, 9, 8, 7]

console.log(heap.peek());   // 1  — O(1), no removal
console.log(heap.pop());    // 1  — extract minimum
console.log(heap.pop());    // 2
console.log(heap.pop());    // 3
console.log(heap.size);     // 4  — four elements remain

// Build heap from array in O(n) via heapify
function buildMinHeap(arr) {
  const h = [...arr];
  // Start at last non-leaf and sift down toward root
  for (let i = Math.floor(h.length / 2) - 1; i >= 0; i--) {
    siftDown(h, i);
  }
  return h;
}

function siftDown(h, i) {
  const n = h.length;
  while (true) {
    let smallest = i;
    const l = 2 * i + 1, r = 2 * i + 2;
    if (l < n && h[l] < h[smallest]) smallest = l;
    if (r < n && h[r] < h[smallest]) smallest = r;
    if (smallest === i) break;
    [h[i], h[smallest]] = [h[smallest], h[i]];
    i = smallest;
  }
}

const built = buildMinHeap([5, 3, 8, 1, 9, 2, 7]);
console.log(built[0]); // 1 — minimum is always at index 0

// ── Heap array layout — index arithmetic reference ──────────────
//
// Array:  [90, 75, 85, 55, 60, 70, 80]
// Index:    0   1   2   3   4   5   6
//
// Tree shape (max-heap):
//           90  (index 0)
//          /  \
//        75    85  (index 1, 2)
//       / \   / \
//      55 60 70  80  (index 3,4,5,6)
//
// Formulas (0-indexed):
//   parent(i)      = Math.floor((i - 1) / 2)
//   leftChild(i)   = 2*i + 1
//   rightChild(i)  = 2*i + 2
//
// Check index 1 (value 75):
//   parent  = floor((1-1)/2) = 0 → value 90 ✓ (90 >= 75, max-heap holds)
//   left    = 2*1+1 = 3      → value 55 ✓ (75 >= 55)
//   right   = 2*1+2 = 4      → value 60 ✓ (75 >= 60)
//
// ── BST vs Heap comparison ──────────────────────────────────────
//
//              BST                   HEAP
// Ordering:   full BST property      weak heap property only
// In-order:   sorted output          NOT sorted
// Find min:   O(log n) - leftmost    O(1) - index 0
// Find max:   O(log n) - rightmost   O(1) - index 0 (max-heap)
// Insert:     O(log n)               O(log n)
// Delete any: O(log n)               O(log n)
// Build:      O(n log n)             O(n) heapify
// Storage:    pointer-based nodes    flat array (cache-friendly)
//
// ── O(n) heapify intuition ──────────────────────────────────────
// n/2 nodes are leaves     → 0 sift-down work
// n/4 nodes are 1 up       → 1 swap each = n/4 work
// n/8 nodes are 2 up       → 2 swaps each = n/4 work
// n/16 nodes are 3 up      → 3 swaps each = 3n/16 work
// Sum: n/4 + n/4 + 3n/16 + ... ≤ n  →  O(n) total
